<script setup lang="ts">
import { ref, computed } from 'vue'
import { backendRequest, backendClient } from '../api/backend-client'
import { backendDemo } from '../lib/backend-demo'
import StructuredFacts from './StructuredFacts.vue'
type Schema={type?:string;title?:string;enum?:unknown[];default?:unknown;properties?:Record<string,Schema>;required?:string[]}
type Module={manifest:{id:string;name:string;version:string;description:string;kind:string;tool?:string;actions:string[];input_schema?:Schema};policy:{enabled:boolean;actions?:string[]}}
type Result={data:Record<string,unknown>;sources?:string[];empty?:boolean;module_version?:string}
const modules=ref<Module[]|null>(null),active=ref<Module|null>(null),result=ref<Result|null>(null),busy=ref(false),error=ref(''),status=ref(''),inputs=ref<Record<string,string|number|boolean>>({})
const fields=computed(()=>Object.entries(active.value?.manifest.input_schema?.properties??{}).filter(([,s])=>['string','number','integer','boolean'].includes(s.type??'string')))
const tasks=computed(()=>Array.isArray(result.value?.data.tasks)?result.value!.data.tasks as {task_id:string;text:string;phase?:string;done:boolean}[]:[])
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const data=await backendRequest<Module[]>('modules');if(!Array.isArray(data))throw new Error('Incomplete modules');modules.value=data.filter(m=>m.policy?.enabled&&m.manifest&&m.manifest.kind!=='tool')}catch{error.value='工具目录没有读取成功，请重试。现有内容仍保留。'}finally{busy.value=false}}
async function open(module:Module){if(busy.value)return;active.value=module;result.value=null;status.value='';inputs.value={};fields.value.forEach(([key,s])=>{if(['string','number','boolean'].includes(typeof s.default))inputs.value[key]=s.default as string|number|boolean});await fetchData()}
async function fetchData(invoke=false){if(!active.value||busy.value)return;busy.value=true;error.value='';try{const m=active.value.manifest;if(invoke){for(const k of m.input_schema?.required??[])if(inputs.value[k]===undefined||inputs.value[k]==='')throw new Error('请填写所有必填项。')}const data=await backendRequest<Result>(invoke?'moduleInvoke':'moduleData',{params:{module_id:m.id},body:invoke?{input:inputs.value,expected_version:m.version,request_id:crypto.randomUUID()}:undefined});if(!data||typeof data.data!=='object')throw new Error('Incomplete module result');result.value=data;status.value=invoke?'工具调用已完成。':'工具数据已读取。'}catch(e){error.value=e instanceof Error&&e.message==='请填写所有必填项。'?e.message:'工具暂时没有返回结果，请重试。输入和原内容仍保留。'}finally{busy.value=false}}
async function setDone(task:{task_id:string;done:boolean}){if(!active.value||busy.value)return;busy.value=true;error.value='';try{const data=await backendRequest<Result>('moduleAction',{params:{module_id:active.value.manifest.id},body:{action:'plan.task.set_done',payload:{task_id:task.task_id,done:!task.done},expected_version:active.value.manifest.version}});result.value=data;status.value='任务状态已保存。';const plan=await backendClient.action();backendDemo.setAction(plan)}catch{error.value='这次操作没有完整完成，请重新读取工具数据核对状态。'}finally{busy.value=false}}
const canComplete=computed(()=>active.value?.manifest.actions.includes('plan.task.set_done')&&active.value.policy.actions?.includes('plan.task.set_done'))
</script>
<template><section class="module-catalog"><div class="ws-section-head"><h2>已发布工具</h2><button class="btn" :disabled="busy" @click="load">{{ busy?'正在读取…':'读取工具目录' }}</button></div><p v-if="error" class="ws-field-error" role="alert">{{ error }}</p><p v-if="status" class="desk-status" role="status">{{ status }}</p><template v-if="modules"><div class="ws-directory"><button class="module-entry" v-for="m in modules" :key="m.manifest.id" :disabled="busy" :aria-pressed="active?.manifest.id===m.manifest.id" @click="open(m)"><strong>{{ m.manifest.name }}</strong><span>{{ m.manifest.description }}</span></button></div><p v-if="!modules.length" class="ws-empty">当前没有已发布且启用的应用工具。</p></template><p v-else class="ws-muted ws-section">按服务返回的发布和启用状态展示，不将未发布工具放入目录。</p><section v-if="active" class="ws-section"><div class="ws-section-head"><h3>{{ active.manifest.name }}</h3><button class="btn" :disabled="busy" @click="fetchData()">刷新工具数据</button></div><p class="ws-muted">{{ active.manifest.description }}</p><form v-if="active.manifest.tool" class="ws-section" @submit.prevent="fetchData(true)"><label v-for="[key,s] in fields" :key="key" class="ws-field">{{ s.title || key }}<select v-if="s.enum" v-model="inputs[key]"><option v-for="v in s.enum" :key="String(v)" :value="v">{{ v }}</option></select><input v-else-if="s.type==='boolean'" v-model="inputs[key]" type="checkbox"/><input v-else-if="s.type==='number'||s.type==='integer'" v-model.number="inputs[key]" type="number" :required="active.manifest.input_schema?.required?.includes(key)"/><input v-else v-model="inputs[key]" maxlength="500" :required="active.manifest.input_schema?.required?.includes(key)"/></label><button class="btn btn--primary" :disabled="busy" type="submit">{{ busy?'正在运行…':'运行工具' }}</button></form><template v-if="result"><p v-if="result.empty" class="ws-empty">工具当前没有可展示的结果。</p><ul v-else-if="tasks.length" class="ws-mini-list"><li v-for="t in tasks" :key="t.task_id" class="live-task"><div><strong>{{ t.text }}</strong><p class="ws-muted">{{ t.phase }} · {{ t.done?'已完成':'待执行' }}</p></div><button v-if="canComplete" class="btn" :disabled="busy" :aria-pressed="t.done" @click="setDone(t)">{{ t.done?'恢复任务':'完成任务' }}</button></li></ul><StructuredFacts v-else :value="result.data"/><p v-if="tasks.length" class="ws-muted ws-section">{{ tasks.filter(t=>t.done).length }} / {{ tasks.length }} 件已完成</p><details v-if="result.sources?.length" class="ws-context"><summary>工具数据来源</summary><ul class="ws-mini-list"><li v-for="s in result.sources" :key="s">{{ s }}</li></ul></details></template></section></section></template>
